const upsertItems = $items('Upsert Departamentos');
if (!upsertItems.length) { return []; }
for (const it of upsertItems) {
  const j = it?.json || {};
  if (j.error) { return []; }
}
const companyName = $items('Build sync_state map')[0]?.json?.company || '';
return [{ json: { companyName, nowIso: new Date().toISOString() } }];

const toIso = (v) => {
  if (v === null || v === undefined) return '';
  const s = String(v).trim();
  if (!s || s.startsWith('0001-01-01')) return '';
  const d = new Date(s.includes('T') ? s : s.replace(' ', 'T'));
  return Number.isNaN(d.getTime()) ? '' : d.toISOString();
};
const maxTsFromRow = (r, fields) => {
  let max = '';
  for (const f of fields) {
    const candidates = [r[f], r[f.charAt(0).toUpperCase() + f.slice(1)]];
    for (const c of candidates) {
      const iso = toIso(c);
      if (iso && (!max || iso > max)) max = iso;
    }
  }
  return max;
};
const __TS_FIELDS__ = ["lastModifiedDateTime", "jobLastModifiedDateTime", "monthClosingLastModifiedDateTime", "analyticConceptLastModifiedDateTime"];
let __GLOBAL_MAX_TS__ = '';

const input = (() => {
  try {
    const snap = $items('BC API - MovimientosProyectos Snapshot');
    if (snap && snap.length) return snap;
  } catch (e) {}
  return $input.all();
})();
if (!input.length) return [];

const companyName = $items('Build sync_state map')[0]?.json?.company || '';
const cleanDate = (v) => {
  const s = String(v ?? '').trim();
  if (!s || s === '0001-01-01') return '';
  return s;
};
const toNum = (v) => {
  if (v === null || v === undefined) return 0;
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};
const toBool = (v) => {
  const s = String(v).toLowerCase();
  return s === 'true' || s === '1' || s === 't' || s === 'yes';
};

const m = new Map();
for (const it of input) {
  const raw = it?.json ?? {};
  const statusCode = Number(raw?.statusCode ?? raw?.response?.statusCode ?? 0);
  if (statusCode >= 400) continue;
  const src = raw?.body ?? raw;
  const chunk = Array.isArray(src.value)
    ? src.value
    : (Array.isArray(src) ? src : (src && typeof src === 'object' && !src.body ? [src] : []));
  if (!Array.isArray(chunk)) continue;
  for (const r of chunk) {
    const __rowMax__ = maxTsFromRow(r, __TS_FIELDS__);
    if (__rowMax__ && (!__GLOBAL_MAX_TS__ || __rowMax__ > __GLOBAL_MAX_TS__)) __GLOBAL_MAX_TS__ = __rowMax__;
    const jobNo = String(r.job ?? r.Job ?? '').trim();
    const year = Number(r.year ?? r.Year ?? 0) || 0;
    const month = Number(r.month ?? r.Month ?? 0) || 0;
    if (!jobNo || !year || !month) continue;
    if (jobNo.startsWith('PP') || jobNo.startsWith('PY')) continue;
    const descripcionCA = String(r.descripcionCA ?? r.DescripcionCA ?? '');
    const typeLine = String(r.typeLine ?? r.TypeLine ?? '');
    const lineType = String(r.lineType ?? r.LineType ?? '').trim();
    const nr = String(r.nr ?? r.Nr ?? '').trim();
    const documentNo = String(r.documentNo ?? r.DocumentNo ?? '').trim();
    const invoiceNeg = Number(r.invoice ?? r.Invoice ?? 0) || 0;
    let invoiceSinK = invoiceNeg;
    if (descripcionCA === 'Kilometraje' || typeLine === 'Resource') invoiceSinK = 0;
    const invoice = invoiceSinK * -1;
    const cost = toNum(r.cost ?? r.Cost);
    const quantity = toNum(r.quantity ?? r.Quantity);
    const key = [jobNo, year, month, nr, typeLine, lineType, descripcionCA, documentNo].join('|');
    if (m.has(key)) {
      const e = m.get(key);
      e.invoice = Number(e.invoice || 0) + invoice;
      e.cost = Number(e.cost || 0) + cost;
      e.quantity = Number(e.quantity || 0) + quantity;
      continue;
    }
    m.set(key, {
      job_no: jobNo,
      year,
      month,
      nr,
      type_line: typeLine,
      line_type: lineType,
      concepto_analitico_descripcion: descripcionCA,
      document_no: documentNo,
      document_date: cleanDate(r.documenDay ?? r.DocumenDay ?? ''),
      timesheet_date: cleanDate(r.workDay ?? r.WorkDay ?? ''),
      invoice,
      cost,
      quantity,
      departamento: String(r.departamento ?? r.Departamento ?? '').trim(),
      description: String(r.descripcion ?? r.Descripcion ?? '').trim(),
      status: String(r.estado ?? r.Estado ?? '').trim(),
      tipo_proyecto: String(r.tipoProyecto ?? r.TipoProyecto ?? '').trim(),
      probability: toNum(r.probability ?? r.Probability),
      do_not_consolidate: toBool(r.doNotConsolidate ?? r.DoNotConsolidate),
      budget_date_year: (() => { const n = toNum(r.budgetDateYear ?? r.BudgetDateYear); return n === 0 && !(r.budgetDateYear ?? r.BudgetDateYear) ? null : n; })(),
      budget_date_month: (() => { const n = toNum(r.budgetDateMonth ?? r.BudgetDateMonth); return n === 0 && !(r.budgetDateMonth ?? r.BudgetDateMonth) ? null : n; })(),
      month_closing_status: String(r.status1 ?? r.Status1 ?? '').trim(),
      concepto_analitico_code: String(r.codigoCA ?? r.CodigoCA ?? '').trim(),
    });
  }
