parameters.jsCode:
const input = $input.all();
if (!input.length) return [];

const companyName = $items('Build sync_state map')[0]?.json?.company || '';
const toNum = (v) => {
  if (v === null || v === undefined) return '';
  const n = Number(v);
  return Number.isFinite(n) ? String(n) : '';
};
const cleanDate = (v) => {
  const s = String(v ?? '').trim();
  if (!s || s === '0001-01-01') return '';
  return s;
};

// Igual que Transform Historico: acumular TODAS las páginas OData
const val = [];
for (const it of input) {
  const raw = it?.json ?? {};
  if (raw.error || raw.statusCode >= 400) continue;
  const src = raw?.body ?? raw;
  const chunk = Array.isArray(src.value)
    ? src.value
    : (Array.isArray(src)
      ? src
      : (src && typeof src === 'object' && !src.body ? [src] : []));
  if (Array.isArray(chunk)) val.push(...chunk);
}
if (!val.length) return [];

const out = [];
const seen = new Set();
for (const r of val) {
  const jobNo = String(r.job ?? '').trim();
  const fecha = cleanDate(r.fecha ?? '');
  if (!jobNo || !fecha) continue;
  if (jobNo.startsWith('PP') || jobNo.startsWith('PY')) continue;
  const key = `${jobNo}|${fecha}`;
  if (seen.has(key)) continue;
  seen.add(key);
  const d = new Date(fecha);
  out.push({
    json: {
      companyName,
      job_no: jobNo,
      closing_date: fecha,
      year: d.getUTCFullYear(),
      month: d.getUTCMonth() + 1,
      billable_price_total: toNum(r.billablePriceTotal),
      cost_total: toNum(r.costTotal),
    },
  });
}
return out;

const upsertItems = $items('Upsert MesesCerrados');
if (!upsertItems.length) { return []; }
for (const it of upsertItems) {
  const j = it?.json || {};
  if (j.error) { return []; }
}
const companyName = $items('Build sync_state map')[0]?.json?.company || '';
return [{ json: { companyName, nowIso: new Date().toISOString() } }];

