parameters.jsCode:
const upsertItems = $items('Upsert ObjectivesByDepartaments');
if (!upsertItems.length) { return []; }
for (const it of upsertItems) {
  const j = it?.json || {};
  if (j.error) { return []; }
}
const companyName = $items('Build sync_state map')[0]?.json?.company || '';
return [{ json: { companyName, nowIso: new Date().toISOString() } }];

const toIso = (v) => {
  if (v === null || v === undefined) return '';
  const s = String(v).trim();
  if (!s || s.startsWith('0001-01-01')) return '';
  const d = new Date(s.includes('T') ? s : s.replace(' ', 'T'));
  return Number.isNaN(d.getTime()) ? '' : d.toISOString();
};
const maxTsFromRow = (r, fields) => {
  let max = '';
  for (const f of fields) {
    const candidates = [r[f], r[f.charAt(0).toUpperCase() + f.slice(1)]];
    for (const c of candidates) {
      const iso = toIso(c);
      if (iso && (!max || iso > max)) max = iso;
    }
  }
  return max;
};
const stableNr = (parts) => {
  const raw = parts.join('|');
  let h = 0;
  for (let i = 0; i < raw.length; i++) {
    h = (h * 31 + raw.charCodeAt(i)) >>> 0;
  }
  return String(h).padStart(10, '0').slice(0, 20);
};
const __TS_FIELDS__ = ["lastModifiedDateTime", "jobLastModifiedDateTime", "monthClosingLastModifiedDateTime"];
let __GLOBAL_MAX_TS__ = '';

const input = $input.all();
if (!input.length) return [];
const val = [];
for (const it of input) {
  const raw = it?.json ?? {};
  if (raw.error || Number(raw.statusCode || 0) >= 400) continue;
  const src = raw?.body ?? raw;
  const chunk = Array.isArray(src.value)
    ? src.value
    : (Array.isArray(src) ? src : (src && typeof src === 'object' && !src.body ? [src] : []));
  if (Array.isArray(chunk)) val.push(...chunk);
}
if (!val.length) return [];

const companyName = $items('Build sync_state map')[0]?.json?.company || '';
const toNum = (v) => {
  const n = Number(v ?? 0);
  return Number.isFinite(n) ? n : 0;
};

const grouped = new Map();
for (const r of val) {
  const __rowMax__ = maxTsFromRow(r, __TS_FIELDS__);
  if (__rowMax__ && (!__GLOBAL_MAX_TS__ || __rowMax__ > __GLOBAL_MAX_TS__)) __GLOBAL_MAX_TS__ = __rowMax__;

  const jobNo = String(r.job ?? r.Job ?? '').trim();
  const year = Number(r.year ?? r.Year ?? 0) || 0;
  const month = Number(r.month ?? r.Month ?? 0) || 0;
  const closingCode = String(r.closingMonthCode ?? r.ClosingMonthCode ?? '').trim();
  const departamento = String(r.departamento ?? r.Departamento ?? '').trim();
  const description = String(r.descripcion ?? r.Descripcion ?? '').trim();
  const status = String(r.estado ?? r.Estado ?? '').trim();
  const tipoProyecto = String(r.tipoProyecto ?? r.TipoProyecto ?? '').trim();
  const probability = String(r.probability ?? r.Probability ?? '').trim();
  const monthClosingStatus = String(r.status1 ?? r.Status1 ?? '').trim();

  if (!jobNo || !year || !month) continue;
  if (jobNo.startsWith('PP') || jobNo.startsWith('PY')) continue;

  const key = [
    companyName,
    jobNo,
    year,
    month,
    closingCode,
    departamento,
    description,
    status,
    tipoProyecto,
    probability,
    monthClosingStatus,
  ].join('|');

  if (!grouped.has(key)) {
    grouped.set(key, {
      companyName,
      job_no: jobNo,
      year,
      month,
      closing_month_code: closingCode,
      departamento,
      description,
      status,
      tipo_proyecto: tipoProyecto,
      probability,
      month_closing_status: monthClosingStatus,
      invoice: 0,
      cost: 0,
      quantity: 0,
    });
  }

  const row = grouped.get(key);
  row.invoice += toNum(r.invoice ?? r.Invoice);
  row.cost += toNum(r.cost ?? r.Cost);
  row.quantity += toNum(r.quantity ?? r.Quantity);
}

const out = [];
for (const row of grouped.values()) {
  const nr = stableNr([
    row.job_no,
    String(row.year),
    String(row.month),
    row.closing_month_code,
    row.departamento,
    row.description,
    row.status,
    row.tipo_proyecto,
    row.probability,
    row.month_closing_status,
  ]);

  out.push({
    json: {
      companyName: row.companyName,
      job_no: row.job_no,
      year: row.year,
      month: row.month,
      closing_month_code: row.closing_month_code,
      nr,
      type_line: 'HPM',
      line_type: 'HIST',
      invoice: String(row.invoice),
      cost: String(row.cost),
      quantity: String(row.quantity),
      departamento: row.departamento,
      description: row.description,
      status: row.status,
      tipo_proyecto: row.tipo_proyecto,
      probability: row.probability,
      do_not_consolidate: 'false',
      budget_date_year: '',
      budget_date_month: '',
      month_closing_status: row.month_closing_status,
      status_filter_only: '',
    },
  });
}

if (__GLOBAL_MAX_TS__ && out.length) {
  out[0].json._maxRowTimestamp = __GLOBAL_MAX_TS__;
}
return out;

const map = $('Build sync_state map').first()?.json || {};
const companyName = map.company || '';
const prevSync = map.syncStateByEntity?.['historico_planificacion_mes'] || '1900-01-01T00:00:00.000Z';
// Advance watermark to NOW()-5min (safety buffer for clock skew / in-flight BC writes).
// Discovery eliminated: no longer depends on _maxRowTimestamp from a discovery pass.
const candidate = new Date(Date.now() - 5 * 60 * 1000).toISOString();
const maxTs = (candidate > prevSync) ? candidate : prevSync;
return [{ json: { companyName, nowIso: maxTs } }];

// Triggered from Split done OR from Skip Result.
const input = $input.all();
if (input.length && input[0]?.json?.skipped) {
  return [{ json: input[0].json }];
}

// Count upserts across partitions (best-effort; $items may only see last run)
let upsertSuccess = 0;
let failed = 0;
let firstErr = '';
try {
  const upsertItems = $items('Upsert HistoricoPlanificacionMes') || [];
  for (const it of upsertItems) {
    const j = it?.json || {};
    const statusCode = Number(j?.statusCode ?? j?.response?.statusCode ?? 0);
    const bodyErr = j?.body?.error?.message || (typeof j?.body === 'string' ? j.body : null);
    const msg = j?.error?.message || j?.message || j?.data?.error || bodyErr || null;
    if (!firstErr && msg) firstErr = String(msg);
    if (msg || statusCode >= 400) { failed++; continue; }
    if (j.job_no !== undefined || j.company_name !== undefined || j.companyName !== undefined) {
      upsertSuccess++;
    }
  }
} catch (e) {}

try {
  const snapItems = $items('BC API - HistoricoPlanificacionMes Snapshot') || [];
  for (const it of snapItems) {
    const j = it?.json || {};
    const statusCode = Number(j?.statusCode ?? 0);
    const msg = j?.error?.message || j?.message || null;
    if (msg || statusCode >= 400) {
      failed++;
      if (!firstErr && msg) firstErr = String(msg);
    }
  }
} catch (e) {}

const res = { key: 'historico_planificacion_mes', causeNode: 'Upsert HistoricoPlanificacionMes' };
if (failed > 0 && upsertSuccess === 0) {
  res.status = 'error'; res.synced = 0; res.failed = failed;
  res.message = firstErr || 'HTTP error';
} else if (failed > 0) {
  res.status = 'partial_error'; res.synced = upsertSuccess; res.failed = failed;
  res.message = firstErr || 'partial errors';
} else {
  res.status = 'ok'; res.synced = upsertSuccess; res.success = upsertSuccess;
}
return [{ json: res }];

