parameters.jsCode:
const upsertItems = $items('Upsert DiasImputacion');
if (!upsertItems.length) { return []; }
for (const it of upsertItems) {
  const j = it?.json || {};
  if (j.error) { return []; }
}
const companyName = $items('Build sync_state map')[0]?.json?.company || '';
return [{ json: { companyName, nowIso: new Date().toISOString() } }];

const body = $json.body ?? $json;
const rawEntities = Array.isArray(body.entities) ? body.entities : [];
const bcToInternal = {
  recursos: 'resource', proyectos: 'job', equipo_proyectos: 'job_team',
  proyectos_tareas: 'job_task', tareas: 'job_task',
  centros_responsabilidad: 'centers_of_responsibility',
  centros_de_responsabilidad: 'centers_of_responsibility',
  configuracion_usuarios: 'user_configuration',
  tecnologias: 'technologies', tipologias: 'typologies', departamentos: 'departments',
  movimientos_proyectos: 'job_ledger_entry_month', planificacion_mes: 'job_planning_line',
  historico_planificacion_mes: 'historico_planificacion_mes', expediente_mes: 'expediente_mes',
  meses_cerrados: 'meses_cerrados', ps_year: 'ps_year', ps_years: 'ps_year',
  objetivos_departamento: 'objectives_by_department', objetivos: 'objectives_by_department',
  dias_imputacion: 'dias_imputacion',
  mayor_analitico: 'job_ledger_entry_line',
  movimientos_proyectos_line: 'job_ledger_entry_line',
  job_ledger_entry_line: 'job_ledger_entry_line',
};
const enabled = [];
for (const raw of rawEntities) {
  const k = String(raw || '').trim().toLowerCase();
  const mapped = bcToInternal[k];
  if (mapped && !enabled.includes(mapped)) enabled.push(mapped);
}
const syncAll = enabled.length === 0;
const partition = body.partition && typeof body.partition === 'object' ? body.partition : {};
return [{
  json: {
    ...$json,
    batch: {
      syncAll,
      enabledEntities: syncAll ? [] : enabled,
      bcEntities: rawEntities,
      reason: body.reason || null,
      queued_at: body.queued_at || null,
      companyFromBody: body.company || null,
      partition,
      sinceYear: body.sinceYear ?? partition.sinceYear ?? null,
      untilYear: body.untilYear ?? partition.untilYear ?? null,
      windowDays: body.windowDays ?? partition.windowDays ?? null,
      maxWindows: body.maxWindows ?? partition.maxWindows ?? null,
    },
  },
}];

const items = $input.all();
const row = items[0]?.json || {};
const id = row.id ?? row.ID ?? null;
if (!id) {
  const errItem = items.find((i) => i.error);
  if (errItem?.error?.message) {
    throw new Error(`Mutex acquire failed: ${errItem.error.message}`);
  }
}
return [{ json: { mutexAcquired: Boolean(id), mutexExecutionId: id } }];

const retryAfterSeconds = 30;
return [{
  json: {
    status: 'busy',
    reason: 'mutex_locked',
    retry_after_seconds: retryAfterSeconds,
    company: $('Resolve Company').first()?.json?.companyName || '',
    timestamp: new Date().toISOString(),
  },
}];

const m = $('Parse Mutex Result').first()?.json || {};
const mutexExecutionId = m.mutexExecutionId ?? null;
if (!mutexExecutionId) {
  throw new Error('004: mutexExecutionId missing after acquire');
}
return [{ json: { mutexAcquired: true, mutexExecutionId } }];

const linkRow = $input.first()?.json || {};
const linkedId = linkRow.id ?? linkRow.ID ?? null;
const mutexExecutionId = $('Parse Mutex Result').first()?.json?.mutexExecutionId;
if (!mutexExecutionId) {
  throw new Error('004: mutexExecutionId missing at Verify Mutex Linked');
}
if (!linkedId || String(linkedId) !== String(mutexExecutionId)) {
  throw new Error(`004: Link Mutex did not update sync_executions id=${mutexExecutionId}`);
}
return [{ json: { mutexExecutionId, mutexLinked: true } }];

