parameters.jsCode:
const input = $input.all();
const jobs = new Set();
for (const it of input) {
  const raw = it?.json ?? {};
  if (raw.error || Number(raw.statusCode) >= 400) continue;
  const src = raw?.body ?? raw;
  const rows = Array.isArray(src.value) ? src.value : (Array.isArray(src) ? src : []);
  for (const r of rows) {
    const jobNo = String(r.no ?? r.No ?? r.job ?? r.Job ?? '').trim();
    if (jobNo && !jobNo.startsWith('PP') && !jobNo.startsWith('PY')) jobs.add(jobNo);
  }
}
return [{ json: { modifiedJobNos: [...jobs].slice(0, 200) } }];

const base = $('Build sync_state map').first()?.json || {};
const incoming = $input.first()?.json || {};
let modifiedJobNos = Array.isArray(base.modifiedJobNos) ? base.modifiedJobNos : [];
if (Array.isArray(incoming.modifiedJobNos)) {
  modifiedJobNos = incoming.modifiedJobNos;
}
let aggregateJobBatchFilter = '';
if (base.needsJobFallback && modifiedJobNos.length) {
  aggregateJobBatchFilter = modifiedJobNos.slice(0, 20)
    .map((j) => "job eq '" + String(j).replace(/'/g, "''") + "'")
    .join(' or ');
}
// Timestamp ORs are illegal in BC OData across distinct fields.
// Prepare* nodes issue one request per field (+ optional jobBatch).
return [{ json: { ...base, modifiedJobNos, aggregateJobBatchFilter } }];

const summary = $('Compute Execution Summary').first()?.json || {};
const releaseRow = $input.first()?.json || {};
const releasedId = releaseRow.id ?? releaseRow.ID ?? null;
const mutexExecutionId = summary.mutexExecutionId ?? $('Parse Mutex Result').first()?.json?.mutexExecutionId;
if (!mutexExecutionId) {
  throw new Error('004: mutexExecutionId missing at Verify Mutex Released');
}
if (!releasedId) {
  throw new Error(`004: Release Mutex did not update sync_executions id=${mutexExecutionId}`);
}
if (String(releasedId) !== String(mutexExecutionId)) {
  throw new Error(`004: Release Mutex row mismatch expected=${mutexExecutionId} got=${releasedId}`);
}
return [{ json: summary }];

const map = ($('Finalize Sync Context').first()?.json || $('Build sync_state map').first().json) || {};
const ls = map.syncStateByEntity?.['job_ledger_entry_month'] || '1900-01-01T00:00:00.000Z';
const companyId = map.companyId;
const env = (($env.BC_ENVIRONMENT && String($env.BC_ENVIRONMENT).trim()) || (() => { throw new Error('BC_ENVIRONMENT is required'); })());
const base = 'https://api.businesscentral.dynamics.com/v2.0/a18dc497-a8b8-4740-b723-65362ab7a3fb/'
  + env + '/api/Power_Solution/PS_API/v2.0/companies(' + companyId + ')/MovimientosProyectosMes';
// Slim select: discovery only extracts year|month (+ timestamps). Snapshot brings full rows.
const select = 'year,month,lastModifiedDateTime,jobLastModifiedDateTime,monthClosingLastModifiedDateTime';
// 3 fields OK here: Discover Partitions UNIONs months — Transform no longer SUMs discovery payloads.
const fields = ["lastModifiedDateTime", "jobLastModifiedDateTime", "monthClosingLastModifiedDateTime"];
const out = [];
for (const f of fields) {
  const filt = f + ' ge ' + ls;
  out.push({
    json: {
      url: base + '?$filter=' + encodeURIComponent(filt) + '&$select=' + select,
      filterField: f,
      entityKey: 'job_ledger_entry_month',
    },
  });
}
if (map.aggregateJobBatchFilter) {
  out.push({
    json: {
      url: base + '?$filter=' + encodeURIComponent(map.aggregateJobBatchFilter) + '&$select=' + select,
      filterField: 'jobBatch',
      entityKey: 'job_ledger_entry_month',
    },
  });
}
return out;

const map = ($('Finalize Sync Context').first()?.json || $('Build sync_state map').first().json) || {};
const ls = map.syncStateByEntity?.['job_planning_line'] || '1900-01-01T00:00:00.000Z';
const companyId = map.companyId;
const env = (($env.BC_ENVIRONMENT && String($env.BC_ENVIRONMENT).trim()) || (() => { throw new Error('BC_ENVIRONMENT is required'); })());
const base = 'https://api.businesscentral.dynamics.com/v2.0/a18dc497-a8b8-4740-b723-65362ab7a3fb/'
  + env + '/api/Power_Solution/PS_API/v2.0/companies(' + companyId + ')/PlanificacionMes';
// Slim select: discovery only extracts year|month (+ timestamps). Snapshot brings full rows.
const select = 'year,month,lastModifiedDateTime,jobLastModifiedDateTime,monthClosingLastModifiedDateTime';
// 3 fields OK: Discover Partitions UNIONs months — Transform reads snapshot (no SUM of discovery).
const fields = ["lastModifiedDateTime", "jobLastModifiedDateTime", "monthClosingLastModifiedDateTime"];

const p = map.partition || {};

// ── MODO forceMonths ──────────────────────────────────────────────────────────
// Si el caller ya indica qué meses regenerar, hacemos una query directa
// año+mes en lugar de las 60-120 ventanas temporales basadas en watermark.
// Esto elimina el "Fallo de watermark": el watermark de job_planning_line
// no avanza correctamente cuando BC hace modificaciones masivas (batch de
// 227k JPL en un día), pisando meses que nunca cambiaron.
// Con este modo: 1 request por mes afectado → Discover Partitions detecta
// exactamente esos meses → snapshot preciso sin false-positives.
const forceMonths = Array.isArray(p.forceMonths) ? p.forceMonths : [];
if (forceMonths.length > 0) {
  const out = [];
  for (const m of forceMonths) {
    const fy = Number(m?.year) || 0;
    const fm = Number(m?.month) || 0;
    if (!fy || !fm) continue;
    const filt = `year eq ${fy} and month eq ${fm}`;
    out.push({
      json: {
        url: base + '?$filter=' + encodeURIComponent(filt) + '&$select=' + select,
        filterField: 'forceMonth',
        entityKey: 'job_planning_line',
        partitionKey: `forceMonth:${fy}|${fm}`,
      },
    });
  }
  if (out.length > 0) return out;
  // Si todos los months eran inválidos, caer al discovery normal (fallback)
}
// ── FIN MODO forceMonths ──────────────────────────────────────────────────────

const sinceYear = Number(p.sinceYear) || new Date().getUTCFullYear() - 2;
const windowDays = Math.max(1, Number(p.windowDays) || 21);
const maxWindows = Math.max(1, Number(p.maxWindows) || 120);

const parseIso = (v) => {
  const d = new Date(String(v || '').replace(' ', 'T'));
  return Number.isNaN(d.getTime()) ? null : d;
};
const minDate = new Date(Date.UTC(sinceYear, 0, 1, 0, 0, 0, 0));
const now = new Date();
const startFromSync = parseIso(ls) || minDate;
const start = startFromSync > minDate ? startFromSync : minDate;
const stepMs = windowDays * 24 * 60 * 60 * 1000;

const windows = [];
let cursor = new Date(start.getTime());
while (cursor < now && windows.length < maxWindows) {
  const end = new Date(Math.min(now.getTime(), cursor.getTime() + stepMs));
  windows.push({ start: new Date(cursor.getTime()), end });
  cursor = end;
}
if (!windows.length) {
  windows.push({ start, end: now });
}

const out = [];
for (const f of fields) {
  for (const w of windows) {
    const filt = `${f} ge ${w.start.toISOString()} and ${f} lt ${w.end.toISOString()}`;
    out.push({
      json: {
        url: base + '?$filter=' + encodeURIComponent(filt) + '&$select=' + select,
        filterField: f,
        entityKey: 'job_planning_line',
        partitionKey: `${f}:${w.start.toISOString()}..${w.end.toISOString()}`,
      },
    });
  }
}
if (map.aggregateJobBatchFilter) {
  out.push({
    json: {
      url: base + '?$filter=' + encodeURIComponent(map.aggregateJobBatchFilter) + '&$select=' + select,
      filterField: 'jobBatch',
      entityKey: 'job_planning_line',
      partitionKey: 'jobBatch',
    },
  });
