  + env + '/api/Power_Solution/PS_API/v2.0/companies(' + companyId + ')/movimientosProyectos';
// Snapshot completo: sin watermark incremental.
// Incremental + UPSERT REPLACE pisaba documentos con un lote parcial
// (health 021 tipo_r_sum 2026-08-13: 26700318 / 26700303).
// Tras el upsert: no insertar si ya hay Close (mismo doc/PK);
// borrar Open de mes cerrado o duplicada; replace de leftovers (último lote).
const filt = "descripcion eq 'Ingresos' and tieneCertificacion eq true";
const select = [
  'entryNo','entryType','documentNo','jobNo','jobTaskNo','no','description',
  'quantity','totalCost','totalPrice','globalDimension1Code','documentDate',
  'month','year','ca','descripcion','tieneCertificacion','lastModifiedDateTime'
].join(',');
return [{
  json: {
    url: base + '?$filter=' + encodeURIComponent(filt) + '&$select=' + select,
    entityKey: 'job_ledger_cert_open',
    mode: 'full_snapshot',
  },
}];

const toIso = (v) => {
  if (v === null || v === undefined) return '';
  const s = String(v).trim();
  if (!s || s.startsWith('0001-01-01')) return '';
  const d = new Date(s.includes('T') ? s : s.replace(' ', 'T'));
  return Number.isNaN(d.getTime()) ? '' : d.toISOString();
};
const input = $input.all();
if (!input.length) return [];
const first = input[0]?.json || {};
if (first.skipped) {
  return [{ json: { skipped: true, key: 'job_ledger_cert_open', companyName: '', rowsJson: '[]', pruneKeysJson: '', batchSize: 0, _maxRowTimestamp: undefined } }];
}

const companyName = $items('Build sync_state map')[0]?.json?.company || '';
const cleanDate = (v) => {
  const s = String(v ?? '').trim();
  if (!s || s === '0001-01-01' || s.startsWith('0001-01-01')) return '';
  return s.length >= 10 ? s.slice(0, 10) : s;
};
const toNum = (v) => {
  if (v === null || v === undefined) return 0;
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};

let __GLOBAL_MAX_TS__ = '';
const m = new Map();
for (const it of input) {
  const raw = it?.json ?? {};
  const statusCode = Number(raw?.statusCode ?? raw?.response?.statusCode ?? 0);
  if (statusCode >= 400) continue;
  const src = raw?.body ?? raw;
  const chunk = Array.isArray(src.value)
    ? src.value
    : (Array.isArray(src) ? src : (src && typeof src === 'object' && !src.body ? [src] : []));
  if (!Array.isArray(chunk)) continue;
  for (const r of chunk) {
    const hasCert = r.tieneCertificacion === true || r.tieneCertificacion === 'true' || r.TieneCertificacion === true;
    if (!hasCert) continue;
    const concepto = String(r.descripcion ?? r.Descripcion ?? '').trim();
    if (concepto !== 'Ingresos') continue;

    const ts = toIso(r.lastModifiedDateTime ?? r.LastModifiedDateTime);
    if (ts && (!__GLOBAL_MAX_TS__ || ts > __GLOBAL_MAX_TS__)) __GLOBAL_MAX_TS__ = ts;

    const jobNo = String(r.jobNo ?? r.JobNo ?? '').trim();
    const year = Number(r.year ?? r.Year ?? 0) || 0;
    const month = Number(r.month ?? r.Month ?? 0) || 0;
    if (!jobNo || !year || !month) continue;
    if (jobNo.startsWith('PP') || jobNo.startsWith('PY')) continue;

    const nr = String(r.no ?? r.No ?? '').trim();
    // Alineado con filas autoritativas de MovimientosProyectosMes (Ingresos Sale)
    const typeLine = 'G/L Account';
    const lineType = 'Billable';
    const documentNo = String(r.documentNo ?? r.DocumentNo ?? '').trim();
    // totalPrice viene negativo en Sale; mismo signo que Mes (invoice neg) → * -1
    const totalPrice = toNum(r.totalPrice ?? r.TotalPrice);
    const invoice = totalPrice * -1;
    const cost = toNum(r.totalCost ?? r.TotalCost);
    const quantity = toNum(r.quantity ?? r.Quantity);
    const key = [jobNo, year, month, nr, typeLine, lineType, concepto, documentNo].join('|');
    if (m.has(key)) {
      const e = m.get(key);
      e.invoice = Number(e.invoice || 0) + invoice;
      e.cost = Number(e.cost || 0) + cost;
      e.quantity = Number(e.quantity || 0) + quantity;
      continue;
    }
    m.set(key, {
      job_no: jobNo,
      year,
      month,
      nr,
      type_line: typeLine,
      line_type: lineType,
      concepto_analitico_descripcion: concepto,
      document_no: documentNo,
      document_date: cleanDate(r.documentDate ?? r.DocumentDate ?? ''),
      timesheet_date: '',
      invoice,
      cost,
      quantity,
      departamento: String(r.globalDimension1Code ?? r.GlobalDimension1Code ?? '').trim(),
      description: String(r.description ?? r.Description ?? '').trim(),
      status: '',
      tipo_proyecto: '',
      probability: 0,
      do_not_consolidate: false,
      budget_date_year: null,
      budget_date_month: null,
      month_closing_status: 'Open',
      concepto_analitico_code: String(r.ca ?? r.Ca ?? '').trim(),
    });
  }
}

const rows = [...m.values()];
const snapshotOk = input.some((it) => {
  const st = Number(it?.json?.statusCode ?? it?.json?.response?.statusCode ?? 0);
  return st < 400;
}) && !input.some((it) => {
  const st = Number(it?.json?.statusCode ?? it?.json?.response?.statusCode ?? 0);
  return st >= 400;
});
const pruneKeys = snapshotOk ? rows.map((r) => ({
  job_no: r.job_no, year: r.year, month: r.month, nr: r.nr,
  type_line: r.type_line, line_type: r.line_type,
  concepto_analitico_descripcion: r.concepto_analitico_descripcion,
  document_no: r.document_no,
})) : null;
const chunkSize = 500;
const out = [];
const chunks = [];
for (let i = 0; i < rows.length; i += chunkSize) chunks.push(rows.slice(i, i + chunkSize));
if (!chunks.length) chunks.push([]);
for (let ci = 0; ci < chunks.length; ci++) {
  const chunk = chunks[ci];
  const isLast = ci === chunks.length - 1;
  out.push({
    json: {
      companyName,
      rowsJson: JSON.stringify(chunk),
      pruneKeysJson: (isLast && pruneKeys) ? JSON.stringify(pruneKeys) : '',
      batchSize: chunk.length,
      _maxRowTimestamp: __GLOBAL_MAX_TS__ || undefined,
      key: 'job_ledger_cert_open',
    },
  });
}
return out;

const upsertItems = $items('Upsert Cert Open Ingresos');
if (!upsertItems.length) { return []; }
for (const it of upsertItems) {
  const j = it?.json || {};
  if (j.error) { return []; }
  if (j.skipped) { return []; }
}
const map = $('Build sync_state map').first()?.json || {};
const companyName = map.company || '';
const prevSync = map.syncStateByEntity?.['job_ledger_cert_open'] || '1900-01-01T00:00:00.000Z';
let maxTs = '';
const transformItems = $items('Transform Cert Open Ingresos');
for (const it of transformItems) {
  const t = it?.json?._maxRowTimestamp;
  if (t && (!maxTs || t > maxTs)) maxTs = t;
}
if (!maxTs || maxTs <= prevSync) {
  maxTs = prevSync;
}
return [{ json: { companyName, nowIso: maxTs } }];

const items = $input.all();
let failed = 0;
let firstErr = '';
let affected = 0;
for (const it of items) {
  const j = it?.json || {};
  if (j.skipped) {
    return [{ json: { key: 'job_ledger_cert_open', status: 'ok', synced: 0, success: 0, skipped: true } }];
  }
  const statusCode = Number(j?.statusCode ?? j?.response?.statusCode ?? 0);
  const bodyErr = j?.body?.error?.message || (typeof j?.body === 'string' ? j.body : null);
  const msg = j?.error?.message || j?.message || j?.data?.error || bodyErr || null;
  if (!firstErr && msg) firstErr = String(msg);
  if (msg || statusCode >= 400) failed++;
  const n = Number(j?.affected ?? 0);
  if (Number.isFinite(n)) affected += n;
}
const success = items.length - failed;
const synced = affected || success;
const res = { key: 'job_ledger_cert_open', causeNode: 'Upsert Cert Open Ingresos' };
if (failed > 0) {
  res.status = 'error';
  res.synced = synced;
  res.failed = failed;
  res.message = firstErr || ('HTTP ' + (items[0]?.json?.statusCode || 'error'));
} else {
  res.status = 'ok';
  res.synced = synced;
  res.success = success;
  res.affected = affected;
}
return [{ json: res }];

const map = ($('Finalize Sync Context').first()?.json || $('Build sync_state map').first().json) || {};
const syncAll = map.syncAll !== false && (!Array.isArray(map.enabledEntities) || map.enabledEntities.length === 0);
const enabled = map.enabledEntities || [];
if (!syncAll && !enabled.includes('job_ledger_entry_line')) {
  return [{ json: { skipped: true, key: 'job_ledger_entry_line' } }];
}
const companyId = map.companyId;
const env = (($env.BC_ENVIRONMENT && String($env.BC_ENVIRONMENT).trim()) || (() => { throw new Error('BC_ENVIRONMENT is required'); })());
const base = 'https://api.businesscentral.dynamics.com/v2.0/a18dc497-a8b8-4740-b723-65362ab7a3fb/'
  + env + '/api/Power_Solution/PS_API/v2.0/companies(' + companyId + ')/movimientosProyectos';
const select = [
  'entryNo','entryType','documentNo','jobNo','jobTaskNo','no','description',
  'quantity','originalUnitCost','totalCost','unitPrice','totalPrice',
  'globalDimension2Code','globalDimension1Code','timeSheetDate','documentDate',
  'origen','linePrice','globalDimension5Code','globalDimension4Code',
  'month','year','ca','descripcion','lastModifiedDateTime'
].join(',');
const sinceYear = Number(map.partition?.sinceYear) || (new Date().getUTCFullYear() - 2);
const untilYear = Number(map.partition?.untilYear) || new Date().getUTCFullYear();
const years = [];
for (let y = sinceYear; y <= untilYear; y++) years.push(y);
const out = [];
for (const y of years) {
  const filt = "year eq '" + y + "'";
  out.push({
    json: {
      url: base + '?$filter=' + encodeURIComponent(filt) + '&$select=' + select,
      entityKey: 'job_ledger_entry_line',
      year: y,
      years,
    },
