  return Number.isNaN(d.getTime()) ? '' : d.toISOString();
};
const pick = (r, ...keys) => {
  for (const k of keys) {
    if (r[k] !== undefined && r[k] !== null && String(r[k]).trim() !== '') return r[k];
  }
  return '';
};
const cleanDate = (v) => {
  const s = String(v ?? '').trim();
