  return [{ json: { skipped: true, key: 'job_ledger_entry_line', companyName: '', rowsJson: '[]', batchSize: 0, yearsJson: '[]', overwriteYears: 'false' } }];
}

const companyName = $items('Build sync_state map')[0]?.json?.company || '';
let years = [];
try {
  for (const it of $items('Prepare Ledger Line')) {
