    const ts = toIso(r.lastModifiedDateTime ?? r.LastModifiedDateTime);
    if (ts && (!__GLOBAL_MAX_TS__ || ts > __GLOBAL_MAX_TS__)) __GLOBAL_MAX_TS__ = ts;
