      quantity: toNum(r.quantity ?? r.Quantity),
      original_unit_cost: toNum(r.originalUnitCost ?? r.OriginalUnitCost),
      total_cost: toNum(r.totalCost ?? r.TotalCost),
      unit_price: toNum(r.unitPrice ?? r.UnitPrice),
      total_price: toNum(r.totalPrice ?? r.TotalPrice),
      line_price: toNum(r.linePrice ?? r.LinePrice),
      concepto_analitico_code: String(pick(r, 'ca', 'CA', 'globalDimension2Code', 'GlobalDimension2Code')),
      concepto_analitico_descripcion: String(pick(r, 'descripcion', 'Descripcion')),
      departamento: String(pick(r, 'globalDimension1Code', 'GlobalDimension1Code')),
      tecnologia: String(pick(r, 'globalDimension4Code', 'GlobalDimension4Code')),
